insert into public.recipes(id,title,category,image_url,payload) select id,title,category,image_url,payload from jsonb_to_recordset($toli$[{"id": "recipe-01", "title": "Tomato & basil spaghetti", "category": "Italian", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-01.jpg", "payload": {"summary": "A bright, silky tomato sauce and a generous handful of fresh basil. Your weeknight pasta ritual.", "prepMinutes": 10, "cookMinutes": 20, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Spaghetti", "quantity": "200", "unit": "g"}, {"name": "Cherry tomatoes", "quantity": "350", "unit": "g"}, {"name": "Garlic cloves", "quantity": "2", "unit": ""}, {"name": "Olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "Fresh basil", "quantity": "10", "unit": "leaves"}, {"name": "Parmesan", "quantity": "30", "unit": "g"}, {"name": "Salt", "quantity": "0.5", "unit": "tsp"}], "steps": ["Bring a large saucepan of water to a boil. Add the salt and cook the spaghetti according to its packet instructions.", "Halve the tomatoes and thinly slice the garlic. Warm the olive oil in a wide pan over medium heat.", "Add the garlic and stir for 30 seconds, without browning it. Add the tomatoes and cook for 12\u201315 minutes until soft.", "Reserve a mug of pasta water before draining. Add the spaghetti and a splash of that water to the tomato pan.", "Toss over gentle heat until glossy. Tear in the basil, grate over the Parmesan and serve immediately."], "tags": ["Vegetarian", "Weeknight", "Pasta"], "tutorial": {"videoID": "lWaBh-r2ZP0", "title": "3 Minute Tomato Pasta Sauce | Jamie Oliver & Davina McCall", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=lWaBh-r2ZP0", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-02", "title": "Weekend berry pancakes", "category": "American", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-02.jpg", "payload": {"summary": "Fluffy little pancakes, fresh berries and a spoonful of maple syrup for a slow morning.", "prepMinutes": 10, "cookMinutes": 15, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "All-purpose flour", "quantity": "140", "unit": "g"}, {"name": "Milk", "quantity": "180", "unit": "ml"}, {"name": "Egg", "quantity": "1", "unit": ""}, {"name": "Baking powder", "quantity": "1.5", "unit": "tsp"}, {"name": "Sugar", "quantity": "1", "unit": "tbsp"}, {"name": "Butter", "quantity": "20", "unit": "g"}, {"name": "Mixed berries", "quantity": "150", "unit": "g"}, {"name": "Maple syrup", "quantity": "2", "unit": "tbsp"}], "steps": ["Stir together the flour, baking powder and sugar. In a second bowl, whisk the milk and egg.", "Melt half the butter. Fold the wet ingredients and melted butter into the flour just until combined; a few small lumps are fine.", "Warm a nonstick pan over medium-low heat and lightly butter it. Spoon in small rounds of batter with space between them.", "Cook until the tops show bubbles and the edges look set, about 2 minutes. Flip and cook the second side until golden and cooked through.", "Repeat with the remaining batter. Serve with washed berries and maple syrup."], "tags": ["Breakfast", "Vegetarian", "Brunch"], "tutorial": {"videoID": "eJLA2RlZNq4", "title": "Pancakes | Buddy Oliver | #CookingBuddies", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=eJLA2RlZNq4", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-03", "title": "Classic cheeseburger & fries", "category": "American", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-03.jpg", "payload": {"summary": "A crisp-edged beef burger with melted cheddar, pickles and oven fries.", "prepMinutes": 15, "cookMinutes": 30, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Ground beef", "quantity": "300", "unit": "g"}, {"name": "Burger buns", "quantity": "2", "unit": ""}, {"name": "Cheddar", "quantity": "40", "unit": "g"}, {"name": "Potatoes", "quantity": "400", "unit": "g"}, {"name": "Olive oil", "quantity": "1", "unit": "tbsp"}, {"name": "Lettuce", "quantity": "2", "unit": "leaves"}, {"name": "Tomato", "quantity": "1", "unit": ""}, {"name": "Pickles", "quantity": "4", "unit": "slices"}, {"name": "Mustard", "quantity": "2", "unit": "tsp"}], "steps": ["Heat the oven to 220\u00b0C / 425\u00b0F. Cut the potatoes into slim fries, dry well, toss with oil and spread out on a tray.", "Bake for 25\u201330 minutes, turning halfway, until browned and tender.", "Shape the beef into two patties without compressing it too much. Season and cook in a hot skillet, turning once.", "Use a food thermometer to check that the center of each beef patty reaches 71\u00b0C / 160\u00b0F. Add cheddar near the end to melt.", "Toast the buns. Layer with mustard, lettuce, tomato, burger and pickles. Serve promptly with the fries."], "tags": ["Dinner", "Comfort food"], "tutorial": {"videoID": "iM_KMYulI_s", "title": "Gordon Ramsay's perfect burger tutorial | GMA", "author": "Good Morning America", "sourceURL": "https://www.youtube.com/watch?v=iM_KMYulI_s", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-04", "title": "Margherita pizza", "category": "Italian", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-04.jpg", "payload": {"summary": "Tomato, mozzarella and basil on a golden crust. A simple pizza night made at home.", "prepMinutes": 20, "cookMinutes": 15, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Ready-to-bake pizza dough", "quantity": "350", "unit": "g"}, {"name": "Crushed tomatoes", "quantity": "150", "unit": "g"}, {"name": "Mozzarella", "quantity": "125", "unit": "g"}, {"name": "Olive oil", "quantity": "1", "unit": "tbsp"}, {"name": "Fresh basil", "quantity": "8", "unit": "leaves"}, {"name": "Flour for dusting", "quantity": "1", "unit": "tbsp"}], "steps": ["Heat the oven to 240\u00b0C / 465\u00b0F with a sturdy baking tray inside. Follow the dough packaging if it specifies a lower temperature.", "Drain and tear the mozzarella. Season the crushed tomatoes with a small pinch of salt.", "On lightly floured baking paper, stretch the dough into a round with a slightly thicker edge.", "Spread a thin layer of tomato over the center and scatter the mozzarella. Transfer with the paper onto the hot tray.", "Bake for 12\u201315 minutes, until the base is cooked and the edge is golden. Finish with basil and olive oil before slicing."], "tags": ["Vegetarian", "Weekend", "Pizza"], "tutorial": {"videoID": "1-SJGQ2HLp8", "title": "How to Make Perfect Pizza | Gennaro Contaldo", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=1-SJGQ2HLp8", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-05", "title": "Lemon herb salmon", "category": "European", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-05.jpg", "payload": {"summary": "Golden salmon with lemon, herbs and a fresh side salad. Clean flavors and very little washing up.", "prepMinutes": 10, "cookMinutes": 15, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Salmon fillets", "quantity": "300", "unit": "g"}, {"name": "Olive oil", "quantity": "1", "unit": "tbsp"}, {"name": "Lemon", "quantity": "1", "unit": ""}, {"name": "Fresh parsley", "quantity": "2", "unit": "tbsp"}, {"name": "Garlic clove", "quantity": "1", "unit": ""}, {"name": "Mixed salad leaves", "quantity": "100", "unit": "g"}], "steps": ["Pat the salmon dry. Finely chop the parsley and garlic and grate a little lemon zest.", "Warm a nonstick skillet over medium heat with the olive oil. Place the fillets skin-side down if they have skin.", "Cook gently for 4\u20136 minutes, turn carefully, and cook until the thickest part reaches 63\u00b0C / 145\u00b0F on a food thermometer.", "Turn off the heat. Add the garlic, parsley, zest and a squeeze of lemon to the warm pan.", "Serve with washed salad leaves and extra lemon wedges. Check carefully for bones."], "tags": ["Seafood", "Weeknight", "Gluten-free"], "tutorial": {"videoID": "6OBoHKRQdHI", "title": "7- Minute Salmon Piccata - Seared Salmon with Lemon Butter Pan Sauce - Food Wishes", "author": "Food Wishes", "sourceURL": "https://www.youtube.com/watch?v=6OBoHKRQdHI", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-06", "title": "Pepper steak skillet", "category": "French-inspired", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-06.jpg", "payload": {"summary": "A bistro-style steak with cracked pepper and a quick pan sauce.", "prepMinutes": 10, "cookMinutes": 20, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Beef steaks", "quantity": "350", "unit": "g"}, {"name": "Olive oil", "quantity": "1", "unit": "tbsp"}, {"name": "Butter", "quantity": "15", "unit": "g"}, {"name": "Black pepper", "quantity": "1", "unit": "tsp"}, {"name": "Beef stock", "quantity": "100", "unit": "ml"}, {"name": "Cream", "quantity": "60", "unit": "ml"}, {"name": "Green beans", "quantity": "200", "unit": "g"}], "steps": ["Pat the steaks dry and season with salt and cracked pepper. Heat a heavy skillet over medium-high heat.", "Add the oil and sear both sides. Lower the heat and continue cooking until the center reaches at least 63\u00b0C / 145\u00b0F; rest for 3 minutes.", "Meanwhile, boil the beans until tender. Drain and keep warm.", "With the steak resting, lower the pan heat and add the stock. Scrape up the browned juices, then stir in cream and butter.", "Simmer briefly until lightly thickened. Spoon the sauce over the rested steak and serve with beans."], "tags": ["Dinner", "Bistro"], "tutorial": {"videoID": "cdjcz73EEtc", "title": "Steak au Poivre  \"Pepper Steak\"", "author": "Food Wishes", "sourceURL": "https://www.youtube.com/watch?v=cdjcz73EEtc", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-07", "title": "Rustic vegetable soup", "category": "European", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-07.jpg", "payload": {"summary": "A cozy pot of tomatoes, garden vegetables and beans, perfect with a slice of crusty bread.", "prepMinutes": 15, "cookMinutes": 30, "servings": 4, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Onion", "quantity": "1", "unit": ""}, {"name": "Carrots", "quantity": "2", "unit": ""}, {"name": "Celery stalks", "quantity": "2", "unit": ""}, {"name": "Zucchini", "quantity": "1", "unit": ""}, {"name": "Chopped tomatoes", "quantity": "400", "unit": "g"}, {"name": "Cooked white beans", "quantity": "240", "unit": "g"}, {"name": "Vegetable stock", "quantity": "900", "unit": "ml"}, {"name": "Olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "Dried thyme", "quantity": "1", "unit": "tsp"}], "steps": ["Wash the vegetables. Peel and dice the onion and carrots; chop the celery and zucchini into similar small pieces.", "Warm the oil in a large pot. Add onion, carrot and celery and cook gently for 8 minutes, stirring often.", "Add the zucchini, tomatoes, thyme and stock. Bring to a boil, then lower to a simmer for 20 minutes.", "Rinse the cooked beans and add them to the pot. Simmer for another 5 minutes until everything is piping hot.", "Taste, season and serve. Cool leftovers promptly and refrigerate within 2 hours."], "tags": ["Vegan", "One pot", "Lunch"], "tutorial": {"videoID": "LrKhcvZYFdQ", "title": "Easy Vegetable Soup Recipe", "author": "Inspired Taste", "sourceURL": "https://www.youtube.com/watch?v=LrKhcvZYFdQ", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-08", "title": "Market garden salad", "category": "European", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-08.jpg", "payload": {"summary": "Crunchy greens, cucumber and tomatoes with a sharp little mustard dressing.", "prepMinutes": 15, "cookMinutes": 0, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Mixed salad leaves", "quantity": "120", "unit": "g"}, {"name": "Cucumber", "quantity": "0.5", "unit": ""}, {"name": "Cherry tomatoes", "quantity": "150", "unit": "g"}, {"name": "Red onion", "quantity": "0.25", "unit": ""}, {"name": "Olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "Lemon juice", "quantity": "1", "unit": "tbsp"}, {"name": "Dijon mustard", "quantity": "1", "unit": "tsp"}, {"name": "Crusty bread", "quantity": "2", "unit": "slices"}], "steps": ["Wash the leaves and vegetables and dry them well. Tear larger leaves into bite-size pieces.", "Slice the cucumber, halve the tomatoes and thinly slice the onion.", "Whisk the oil, lemon juice and mustard with a small pinch of salt and pepper.", "Put the vegetables in a wide bowl. Add just enough dressing to coat and toss gently.", "Serve straight away with toasted bread. Keep any extra dressing chilled in a covered container."], "tags": ["Vegan", "Quick", "Lunch"], "tutorial": {"videoID": "vLP2CXsQGGo", "title": "Jamie's Ministry of Food - everyday green chopped salad", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=vLP2CXsQGGo", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-09", "title": "Sunday roast chicken", "category": "British", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-09.jpg", "payload": {"summary": "A golden roast chicken with crisp potatoes, lemon and fragrant herbs.", "prepMinutes": 20, "cookMinutes": 80, "servings": 4, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Weekend project", "ingredients": [{"name": "Whole chicken", "quantity": "1.4", "unit": "kg"}, {"name": "Potatoes", "quantity": "800", "unit": "g"}, {"name": "Lemon", "quantity": "1", "unit": ""}, {"name": "Garlic cloves", "quantity": "4", "unit": ""}, {"name": "Olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "Rosemary", "quantity": "3", "unit": "sprigs"}, {"name": "Carrots", "quantity": "4", "unit": ""}], "steps": ["Heat the oven to 200\u00b0C / 390\u00b0F. Keep raw chicken and its utensils separate from other ingredients; do not wash raw poultry.", "Scrub and cut the potatoes and carrots. Toss them with half the oil and rosemary in a roasting tray.", "Pat the chicken dry, rub with the remaining oil and season. Place on top of the vegetables with lemon halves and garlic around it.", "Roast for approximately 75\u201390 minutes, checking as needed. The thickest part of the breast and thigh must reach 74\u00b0C / 165\u00b0F, without touching bone.", "Rest for 10 minutes before carving. Check the vegetables are tender and serve with the pan juices."], "tags": ["Sunday lunch", "Family", "Roast"], "tutorial": {"videoID": "bJeUb8ToRIw", "title": "How to Cook Roast Chicken | Jamie Oliver", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=bJeUb8ToRIw", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-10", "title": "Tomato basil bruschetta", "category": "Italian", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-10.jpg", "payload": {"summary": "Juicy chopped tomatoes on warm toasted bread, finished with basil and good olive oil.", "prepMinutes": 15, "cookMinutes": 5, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Ripe tomatoes", "quantity": "300", "unit": "g"}, {"name": "Sourdough bread", "quantity": "4", "unit": "slices"}, {"name": "Garlic clove", "quantity": "1", "unit": ""}, {"name": "Olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "Fresh basil", "quantity": "6", "unit": "leaves"}, {"name": "Balsamic vinegar", "quantity": "1", "unit": "tsp"}], "steps": ["Wash and dice the tomatoes. Put them in a bowl with a pinch of salt and leave for 5 minutes.", "Tear the basil and fold it into the tomatoes with half the oil and the balsamic vinegar.", "Toast or grill the bread until golden on both sides.", "Cut the garlic clove in half and lightly rub the cut side across the warm bread.", "Spoon on the tomatoes, drizzle with the remaining oil and serve before the bread softens."], "tags": ["Vegan", "Starter", "Quick"], "tutorial": {"videoID": "Q3xg35pcLyo", "title": "How to Make Italian BRUSCHETTA - Easy Appetizer", "author": "Natashas Kitchen", "sourceURL": "https://www.youtube.com/watch?v=Q3xg35pcLyo", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-11", "title": "Roasted tomato mozzarella toast", "category": "Italian-inspired", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-11.jpg", "payload": {"summary": "Sweet roasted tomatoes, soft mozzarella and golden toast for a generous lunch.", "prepMinutes": 10, "cookMinutes": 25, "servings": 2, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Easy", "ingredients": [{"name": "Cherry tomatoes", "quantity": "300", "unit": "g"}, {"name": "Mozzarella", "quantity": "125", "unit": "g"}, {"name": "Sourdough bread", "quantity": "2", "unit": "thick slices"}, {"name": "Olive oil", "quantity": "1", "unit": "tbsp"}, {"name": "Dried oregano", "quantity": "0.5", "unit": "tsp"}, {"name": "Fresh basil", "quantity": "6", "unit": "leaves"}], "steps": ["Heat the oven to 200\u00b0C / 390\u00b0F. Toss the tomatoes with the oil and oregano in a small baking dish.", "Roast for about 20 minutes until softened and beginning to burst.", "Toast the bread. Drain and tear the mozzarella.", "Top the toast with warm tomatoes and mozzarella. Return to the oven for 3\u20135 minutes if you prefer melted cheese.", "Scatter over basil and serve warm, spooning a little tomato juice over each slice."], "tags": ["Vegetarian", "Lunch", "Toast"], "tutorial": {"videoID": "OMqQjB4pJVY", "title": "Easy Mozzarella And Tomato Bruschetta Recipe | Mary Berry's Quick Cooking | Mary Berry", "author": "Mary Berry", "sourceURL": "https://www.youtube.com/watch?v=OMqQjB4pJVY", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}, {"id": "recipe-12", "title": "Herb chicken tray bake", "category": "European", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/recipe-12.jpg", "payload": {"summary": "Chicken, potatoes and herbs roasted together in one easy tray.", "prepMinutes": 15, "cookMinutes": 45, "servings": 3, "calories": 0, "protein": 0, "carbs": 0, "fat": 0, "difficulty": "Weekend project", "ingredients": [{"name": "Chicken thighs", "quantity": "600", "unit": "g"}, {"name": "Small potatoes", "quantity": "500", "unit": "g"}, {"name": "Red onion", "quantity": "1", "unit": ""}, {"name": "Carrots", "quantity": "3", "unit": ""}, {"name": "Olive oil", "quantity": "2", "unit": "tbsp"}, {"name": "Dried oregano", "quantity": "1", "unit": "tsp"}, {"name": "Lemon", "quantity": "1", "unit": ""}], "steps": ["Heat the oven to 210\u00b0C / 410\u00b0F. Wash and halve the potatoes, cut the onion into wedges and slice the carrots.", "Put the vegetables in a roasting tray with the oil, oregano and lemon wedges. Toss to coat.", "Place the chicken on top and season. Keep raw poultry utensils separate from ready-to-eat foods.", "Roast for 40\u201350 minutes. Check the thickest part of each thigh reaches 74\u00b0C / 165\u00b0F with a food thermometer and the potatoes are tender.", "Rest for 5 minutes and serve with the roasted vegetables and pan juices."], "tags": ["One tray", "Family", "Dinner"], "tutorial": {"videoID": "zyF_0hqLqHA", "title": "Mediterranean Baked Chicken Dinner (Lemon Garlic Chicken Potato Bake)", "author": "RecipeTin Eats", "sourceURL": "https://www.youtube.com/watch?v=zyF_0hqLqHA", "provider": "YouTube", "note": "A creator's take on this dish. Ingredients and timings may differ from Toli's recipe."}}}]$toli$::jsonb) as r(id text,title text,category text,image_url text,payload jsonb) on conflict(id) do nothing;
insert into public.cooking_videos(id,title,category,image_url,video_url,payload) select id,title,category,image_url,video_url,payload from jsonb_to_recordset($toli$[{"id": "cooking-01", "title": "Skillet pasta", "category": "Pasta", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-01.jpg", "video_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-01.mp4", "payload": {"chef": "cottonbro studio", "durationSeconds": 20, "summary": "A sourced cooking film, presented as a replay. Filmmaker credit: cottonbro studio. No live audience or message delivery is implied.", "recipeID": "recipe-01"}}, {"id": "cooking-02", "title": "Pancakes on the griddle", "category": "Breakfast", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-02.jpg", "video_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-02.mp4", "payload": {"chef": "Vlada Karpovich", "durationSeconds": 10, "summary": "A sourced cooking film, presented as a replay. Filmmaker credit: Vlada Karpovich. No live audience or message delivery is implied.", "recipeID": "recipe-02"}}, {"id": "cooking-03", "title": "Colorful skillet vegetables", "category": "Vegetables", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-03.jpg", "video_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-03.mp4", "payload": {"chef": "Kampus Production", "durationSeconds": 8, "summary": "A sourced cooking film, presented as a replay. Filmmaker credit: Kampus Production. No live audience or message delivery is implied.", "recipeID": null}}, {"id": "cooking-04", "title": "Seasoning grilled steak", "category": "Dinner", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-04.jpg", "video_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-04.mp4", "payload": {"chef": "Kuiyibo Campos", "durationSeconds": 20, "summary": "A sourced cooking film, presented as a replay. Filmmaker credit: Kuiyibo Campos. No live audience or message delivery is implied.", "recipeID": "recipe-06"}}, {"id": "cooking-05", "title": "Kneading homemade dough", "category": "Baking", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-05.jpg", "video_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-05.mp4", "payload": {"chef": "Pavel Danilyuk", "durationSeconds": 13, "summary": "A sourced cooking film, presented as a replay. Filmmaker credit: Pavel Danilyuk. No live audience or message delivery is implied.", "recipeID": "recipe-04"}}, {"id": "cooking-06", "title": "Tossing a fresh salad", "category": "Salads", "image_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-06.jpg", "video_url": "https://hdapofqufmxlghmcrftg.supabase.co/storage/v1/object/public/toli-catalog/cooking-06.mp4", "payload": {"chef": "Mikhail Nilov", "durationSeconds": 20, "summary": "A sourced cooking film, presented as a replay. Filmmaker credit: Mikhail Nilov. No live audience or message delivery is implied.", "recipeID": "recipe-08"}}]$toli$::jsonb) as v(id text,title text,category text,image_url text,video_url text,payload jsonb) on conflict(id) do nothing;
